import { Category, ErrorEvent, Identity, PartyIdentification, UserEngagement } from '../events';
/**
Description: Click a link.
*/
export type AnchorClick = {
    events: Array<UserEngagement | Identity | PartyIdentification | ErrorEvent>;
}

export class AnchorClickBuilder {

    private anchorClick: AnchorClick = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private userEngagement!: UserEngagement;

    public withErrorEvent(errorEvent: ErrorEvent) : AnchorClickBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : AnchorClickBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : AnchorClickBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withUserEngagement(userEngagement: UserEngagement) : AnchorClickBuilder {
        this.userEngagement = userEngagement;
        return this;
    }

    public build() : AnchorClick {
        if(this.errorEvent) {
            this.anchorClick.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.anchorClick.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.anchorClick.events.push(this.partyIdentification);
        }
        if(this.userEngagement) {
            this.anchorClick.events.push(this.userEngagement);
        }

        return this.anchorClick;
    }
}
